"""산초 설명(SCH_NOTE) 만들기. build_sancho.py에서 부름."""
def d_(s):
    y, m, d = s.split("-"); return f"{int(y)}.{int(m)}.{int(d)}"
def c3(v): return "·".join(map(str, v[:3]))

def make_note(M, E, ST, SRC, NG, NGo, NA, NPK, MIN_TOT, NTIE, NTIEG):
    CLUB_KO = {"bvbsa": "도르트문트", "munsa": "맨체스터 유나이티드", "chesa": "첼시", "avlsa": "애스턴 빌라"}
    L = [
        f"제이든 산초(도르트문트·맨체스터 유나이티드·첼시·애스턴 빌라)의 클럽 공식 경기 {NG}경기({d_(M[0][0])} 프랑크푸르트전 ~ {d_(M[-1][0])} 프라이부르크전)에서 나온 {NGo}골 {NA}도움(PK 골 {NPK}개), 친선경기·잉글랜드 대표팀·유소년(맨시티 U18·U21·유스리그, 도르트문트 U19·유스리그)·도르트문트 II(레기오날리가 3경기) 제외",
        "클럽별 경기·골·도움: " + ", ".join(f"{CLUB_KO[k]} {c3(v)}" for k, v in ST.items()) + f"(도르트문트는 2017~2021과 2024년 1~6월 임대를 합침, 맨유는 2021~2023과 2024.8.10 커뮤니티 실드). 출전 분 합계 {MIN_TOT:,}분",
        f"출처: 경기 목록·출전 분(연장 반영)은 Transfermarkt 선수 경기 성적, 골 시간·골 뒤 스코어·PK·도움은 Transfermarkt 경기 리포트({NG}경기 전부)를 쓰고 FotMob 경기 이벤트(골·도움이 있는 118경기)와 대조함. 출전 분은 추정 없이 모두 Transfermarkt 기록",
        "경기 수·골은 영어 위키백과 클럽·시즌·대회별 기록과 모두 같고(위키백과 경력 합계 324경기는 도르트문트 II 3경기를 더한 값), FotMob 경력의 골 71개와도 같음. 출전 분은 FotMob과 1분 차이가 22경기에 있어 Transfermarkt 값을 씀",
        "골: Transfermarkt와 FotMob이 모든 경기에서 수·스코어·PK 여부가 같음(PK 골 3개: 2020.9.14 뒤스부르크전(포칼), 2020.10.28 제니트전(챔스), 2021.2.27 빌레펠트전; 자책골 없음). 2018.8.20 퓌르트전(포칼 1라운드) 연장 120+1분 로이스 골에 준 도움은 연장 121분으로 계산함. 2019.8.23 쾰른전 알카세르 골에 준 도움은 Transfermarkt 90분, FotMob 90+4분이라 94분으로 계산함(그 밖의 분 차이는 Transfermarkt 표기)",
        f"도움: 2014년 8월 이후 기록이라 Transfermarkt와 FotMob이 함께 센 것만 쓰고, Transfermarkt에만 있는 것은 다른 출처 2곳(경기 기사·구단 공식 기록)이 확인한 것만 넣음. 도움 {NA} = Transfermarkt 리포트 86 − PK 유도 4(2018.12.1 프라이부르크전 40분 로이스 PK, 2019.3.9 슈투트가르트전 62분 로이스 PK, 2024.1.20 쾰른전 58분 퓔크루크 PK, 2024.9.28 브라이턴전 28분 팔머 PK) − 슈팅 리바운드 1(2019.2.9 호펜하임전 43분 괴체) − 출처가 갈린 1(아래)",
        "Transfermarkt에만 있어 기사로 확인해 넣은 도움 4개: 2018.8.20 퓌르트전 120+1분 로이스(경기 기사 2건이 산초의 크로스·컷백을 확인), 2018.11.24 마인츠전 76분 피슈체크(BVB 공식 기록·Sportsmole·경기 기사), 2019.9.14 레버쿠젠전 83분 게레이루(BVB 공식 기록·AFP 계열 기사·Sky Italia 기사; Sky Sports 라인업 페이지에는 도움 없음), 2020.9.14 뒤스부르크전 58분 로이스(경기 득점 기록·독일 보도; Transfermarkt 도움 유형은 프리킥, 기사는 산초의 크로스로 적음)",
        "확인하지 못해 뺀 도움 1개: 2020.10.31 빌레펠트전 53분 훔멜스 골은 Transfermarkt·bundesliga.com이 산초의 코너(훔멜스 몸에 맞고 들어감)로 적었으나 FotMob·ESPN·Sportsmole 등은 뫼니에 도움으로 적어 출처가 갈림. 산초 도움 합계 비교: Transfermarkt 86·FotMob 경기 이벤트 76·FotMob 경력 76·이 계산기 " + str(NA) + "(FotMob에만 있는 산초 도움은 없음)",
        "날짜는 현지 날짜(모두 유럽, Transfermarkt 리포트 날짜와 같음). 중립 경기(2024.6.1 챔스 결승, 2024.8.10 커뮤니티 실드, 2023.4.23 FA컵 준결승)는 홈·원정 표기가 출처마다 다르나 단판이라 계산에 영향 없음",
        f"상대 Elo는 같은 경기를 다룬 다른 선수 자료(로이스·괴체·홀란·벨링엄·호날두 등) 값, 같은 팀·같은 시즌 다른 선수 자료 값, 그 시즌 최종 순위를 리그 모형에 넣은 값, 직접 추정 순으로 씀"
        f"(기록 {len(E)}개: 같은 경기 {SRC['같은 경기 다른 선수 자료']}, 같은 팀·시즌 {SRC['팀×시즌 통합표']}, 순위표+모형 {SRC['순위표+리그 모형']}, 직접 {SRC['직접 추정']})",
        "순위표+모형: 미들즈브러 2021-22 챔피언십 7위(FotMob 최종 순위) 1642(기존 자료의 챔피언십 7위 값). 직접 추정(모두 '추정'): 레기아 바르샤바 2024-25 폴란드 5위(FotMob 최종 순위) 1490(기존 자료 폴란드 3위 1480과 10위 1500의 중간값), 유르고르덴 2024 스웨덴 4위(FotMob 최종 순위) 1503(기존 자료 말뫼 1위 1555와 5위 1450의 중간값)",
        "대회 비중: 포칼·FA컵·리그컵은 국내컵(16강까지 낮은 비중, 8강 이후 높은 비중), 독일 슈퍼컵·커뮤니티 실드는 국내컵 결승으로 계산함. 챔스 리그 페이즈(2024-25부터)·유로파 리그 페이즈(2025-26)·컨퍼런스 리그 페이즈는 조별과 같이, 2022-23 유로파 32강 플레이오프(바르셀로나전)는 유로파 토너먼트로 계산함",
        f"두 경기 합산(챔스·유로파·컨퍼런스 토너먼트) 기록 {NTIE}개({NTIEG}경기)는 합산 S로 계산함. 원정 다득점은 UEFA 대회 2020-21까지(2021.2.17 세비야전 챔스 16강 1차전), 2021-22부터는 연장만 있고 원정 다득점 없음. 산초가 뛰지 않은 다른 차전 스코어(2021.3.9 세비야전 2차전 2-2)는 Transfermarkt 경기 리포트로 채움",
        "시즌 구분: 도르트문트는 7월 10일 기준(로이스·오바메양 선례, 7월 경기는 없음), 맨유·첼시·애스턴 빌라는 8월 1일 기준(2024.8.10 커뮤니티 실드는 2024-25)",
        "수상 기록은 Transfermarkt 업적 페이지 기준: DFB 포칼 2020-21, 독일 슈퍼컵 2019-20, 리그컵 2022-23(Transfermarkt 표기 2023), 컨퍼런스리그 2024-25(첼시), 유로파리그 2025-26(애스턴 빌라), 챔스 준우승 2023-24, 분데스리가 신인상 2018-19, 2020-21 포칼 득점왕(6골), 2018-19 분데스리가 도움 1위(18). 유로 2020·U-17 월드컵(대표팀)은 뺌",
        f"2026.11.12 기준: 마지막 출전은 {d_(M[-1][0])} 프라이부르크전(유로파리그 결승, 9분). 맨체스터 유나이티드와 계약이 2026.6.30 끝나 Transfermarkt에 무소속으로 표기되며 은퇴 발표는 없음. 마지막 반영 경기 {d_(M[-1][0])} 프라이부르크전(2026.11.12 수집)",
    ]
    return "\n".join(L)
